const rows = $input.all().map(i => i.json);

const isTrue = (v) => {
  const s = String(v ?? '').trim().toLowerCase();
  return v === true || s === 'true' || s === 'yes' || s === '1' || s === 'checked';
};

const needDraft = [];
const imageQueue = [];
const needPublish = [];
const needImagePending = [];

for (const r of rows) {
  const approved = isTrue(r.Approved);
  const status = String(r.Status ?? '').trim().toLowerCase();

  const featuredLink = String(r["Featured Image Link"] ?? "").trim();
  const wpFeaturedLink = String(r["WP Featured Image Link"] ?? "").trim();
  const socialMediaImageLink = String(r["Social Media Image Link"] ?? "").trim();
  const ContentTeamApproval = String(r["Content Team Approval"] ?? "").trim().toLowerCase();
  const DMTeamApproval = String(r["DM Team Approval"] ?? "").trim().toLowerCase();

  // Draft
  if (approved && (status === "" || status === "pending")) {
    needDraft.push(r);
  }

  // Image Pending → when BOTH images are missing
  if (
    status === "ready" &&
    ContentTeamApproval === "ok" &&
    DMTeamApproval === "ok" &&
    featuredLink === "" &&
    socialMediaImageLink === ""
  ) {
    needImagePending.push(r);
  }

  // Image Queue → when BOTH images are available
  if (
     status === "ready" &&
     ContentTeamApproval === "ok" &&
    DMTeamApproval === "ok" &&
    featuredLink !== "" &&
    socialMediaImageLink !== ""
  ) {
    imageQueue.push(r);
  }

  // Publish queue → ready + WP image exists + approvals done
  if (
    status === "ready" &&
    wpFeaturedLink !== "" &&
    socialMediaImageLink !== "" &&
    ContentTeamApproval === "ok" &&
    DMTeamApproval === "ok"
  ) {
    needPublish.push(r);
  }
}

return [
  {
    json: {
      needDraft,
      imageQueue,
      needPublish,
      needImagePending,
      counts: {
        total: rows.length,
        needDraft: needDraft.length,
        imageQueue: imageQueue.length,
        needPublish: needPublish.length,
        needImagePending: needImagePending.length
      }
    }
  }
];

// Get document content from Gemini node
const raw = $('Gemini: Generate Blog HTML1').first().json.content.parts[0].text || '';

// Extract focus keyword
const match = raw.match(/<!--\s*SEO_FOCUS_KEYWORD:\s*(.*?)\s*-->/i);

const focusKeyword = match ? match[1].trim() : '';

return [
  {
    json: {
      focusKeyword
    }
  }
];

const row = $json.imageQueue[0];

const featuredLink = String(row["Featured Image Link"] || "").trim();
const socialLink = String(row["Social Media Image Link"] || "").trim();
const focusKeyword = String(row["Focus Keyword"] || row.Topic || "").trim();

function driveDirectDownload(url) {
  let fileId = "";
  const m1 = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  const m2 = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);

  if (m1) fileId = m1[1];
  else if (m2) fileId = m2[1];

  if (!fileId) return "";
  return `https://drive.google.com/uc?export=download&id=${fileId}`;
}

function oneDriveDirectDownload(url) {
  if (url.includes("download=1")) return url;
  return url.includes("?") ? `${url}&download=1` : `${url}?download=1`;
}

function buildDownload(url) {
  if (!url) return "";

  if (url.includes("drive.google.com")) {
    return driveDirectDownload(url);
  }

  if (url.includes("1drv.ms") || url.includes("onedrive.live.com")) {
    return oneDriveDirectDownload(url);
  }

  return url;
}

const items = [];

if (featuredLink) {
  items.push({
    json: {
      ...row,
      imageType: "featured",
      originalImageLink: featuredLink,
      downloadUrl: buildDownload(featuredLink),
      imageAltText: focusKeyword,
      fileName: "featured.jpg"
    }
  });
}

if (socialLink) {
  items.push({
    json: {
      ...row,
      imageType: "social",
      originalImageLink: socialLink,
      downloadUrl: buildDownload(socialLink),
      imageAltText: focusKeyword,
      fileName: "social.jpg"
    }
  });
}

return items;

const rows = $input.all();
const sourceItems = $('Code: Build Direct Download URL1').all();

const result = {
  Topic: sourceItems[0]?.json?.Topic || '',
  featuredLink: '',
  featuredId: '',
  socialLink: '',
  socialId: ''
};

for (let index = 0; index < rows.length; index++) {
  const item = rows[index];
  const source = sourceItems[index]?.json || {};

  const type = source.imageType || '';
  const wpUrl = item.json.source_url || item.json.guid?.rendered || '';
  const wpId = item.json.id || '';

  if (type === 'featured') {
    result.featuredLink = wpUrl;
    result.featuredId = wpId;
  }

  if (type === 'social') {
    result.socialLink = wpUrl;
    result.socialId = wpId;
  }
}

return [
  {
    json: result,
    pairedItem: rows.map((_, index) => ({ item: index }))
  }
];

/*
 Build a single HTML message for Teams.
 We ignore the batch header row (Topic starting with 'Batch: ').
*/

const topics = items
  .map(i => i.json.Topic)
  .filter(t => t && !t.startsWith('Batch: '));

const htmlList = topics
  .map(t => `<li>${t}</li>`)
  .join('');

const count = topics.length;

return [
  {
    json: {
      html: `<h2><b>✅ Weekly Kleza blog topics are ready.</b></h2>\n<br><br>\n<p>Topics were added to the sheet.</p>\n\n<br>\nPlease review and tick <b>Approved</b> for the topics you want to convert into blog posts.\n<br>\nSheet Link <a href="https://docs.google.com/spreadsheets/d/1MaGXYNxpxM5QV49nAldZu9WA15Nim00tDoei9AtCRx8/edit?gid=0#gid=0">Click Here</a>`
    }
  }
];

// Split Gemini titles JSON into rows for Google Sheets

const input = $input.first().json;

// Gemini output is at: $json.output
let raw = input?.output || '';

if (!raw) {
  throw new Error('No Gemini output found at $json.output');
}

// Remove ```json ... ``` fences if present
raw = String(raw).replace(/```json|```/g, '').trim();

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Gemini output not valid JSON. Raw: ' + raw);
}

// Support both old "topics" and new "titles" formats
let items = [];
if (Array.isArray(data.titles)) {
  items = data.titles;
} else if (Array.isArray(data.topics)) {
  items = data.topics;
}

if (!items.length) {
  throw new Error(
    'No titles/topics found in JSON. Expected { "titles": [ ... ] } or { "topics": [ ... ] }. Got: ' +
      JSON.stringify(data)
  );
}

// Build Indian time (Asia/Kolkata) and format like "2nd Mar 2026, 11:20:05 AM IST"
const now = new Date();

const dateParts = new Intl.DateTimeFormat('en-IN', {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
  timeZone: 'Asia/Kolkata',
}).formatToParts(now);

const dayStr = dateParts.find((p) => p.type === 'day').value;
const monthStr = dateParts.find((p) => p.type === 'month').value;
const yearStr = dateParts.find((p) => p.type === 'year').value;

const dayNum = parseInt(dayStr, 10);

function ordinal(n) {
  const rem10 = n % 10;
  const rem100 = n % 100;
  if (rem10 === 1 && rem100 !== 11) return `${n}st`;
  if (rem10 === 2 && rem100 !== 12) return `${n}nd`;
  if (rem10 === 3 && rem100 !== 13) return `${n}rd`;
  return `${n}th`;
}

const dayWithSuffix = ordinal(dayNum);

const timeStr = new Intl.DateTimeFormat('en-IN', {
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: true,
  timeZone: 'Asia/Kolkata',
}).format(now);

const formatted = `${dayWithSuffix} ${monthStr} ${yearStr}, ${timeStr} IST`;

const output = [];

// 1) Add a header row that will appear ABOVE the topics in Google Sheets
output.push({
  json: {
    Topic: `Batch: Topics generated on ${formatted}`,
    Approved: '',
    Status: 'Batch Header',
    Notes: ''
  }
});

// 2) Add up to 5 topic/title rows
items.slice(0, 5).forEach((t) => {
  output.push({
    json: {
      Topic: String(t.title || t.topic || '').trim(),
      Approved: false,
      Status: 'Pending',
      Notes: ''
    }
  });
});

return output;

