const doc = $input.first().json;
const bodyContent = doc.body?.content || [];
const lists = doc.lists || {};

function escapeHtml(str = '') {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderTextRun(textRun) {
  if (!textRun || !textRun.content) return '';

  let text = escapeHtml(textRun.content).replace(/\n$/, '');
  const style = textRun.textStyle || {};

  if (style.link?.url) {
    text = `<a href="${escapeHtml(style.link.url)}">${text}</a>`;
  }
  if (style.bold) {
    text = `<strong>${text}</strong>`;
  }
  if (style.italic) {
    text = `<em>${text}</em>`;
  }

  return text;
}

function renderParagraphElements(elements = []) {
  return elements
    .map(el => {
      if (el.textRun) return renderTextRun(el.textRun);
      return '';
    })
    .join('')
    .trim();
}

function getPlainParagraphText(elements = []) {
  return elements
    .map(el => el.textRun?.content || '')
    .join('')
    .replace(/\n/g, '')
    .trim();
}

function extractLineValue(label) {
  for (const block of bodyContent) {
    const para = block.paragraph;
    if (!para) continue;

    const plain = getPlainParagraphText(para.elements || []);
    const regex = new RegExp(`^${label}:\\s*(.+)$`, 'i');
    const match = plain.match(regex);
    if (match) return match[1].trim();
  }
  return '';
}

const seoTitle = extractLineValue('SEO Title');
const seoDescription = extractLineValue('SEO Description');
const seoFocusKeyword = extractLineValue('Focus Keyword');
const seoTags = extractLineValue('SEO Tags');

const tagNames = seoTags
  ? seoTags.split(',').map(tag => tag.trim()).filter(Boolean)
  : [];

let html = '';
let h1Title = '';
let currentListId = null;
let currentListTag = null;
let h1Captured = false;

function closeList() {
  if (currentListTag) {
    html += `</${currentListTag}>`;
    currentListId = null;
    currentListTag = null;
  }
}

function getListTag(listId) {
  const list = lists[listId];
  const firstLevel = list?.listProperties?.nestingLevels?.[0];

  if (!firstLevel) return 'ul';

  return 'ul';
}

for (const block of bodyContent) {
  const para = block.paragraph;
  if (!para) continue;

  const plainText = getPlainParagraphText(para.elements || []);
  const richText = renderParagraphElements(para.elements || []);
  const style = para.paragraphStyle?.namedStyleType || 'NORMAL_TEXT';

  if (!plainText) {
    closeList();
    continue;
  }

  // Skip SEO metadata from post body
  if (
    /^SEO Details$/i.test(plainText) ||
    /^SEO Title:/i.test(plainText) ||
    /^SEO Description:/i.test(plainText) ||
    /^Focus Keyword:/i.test(plainText) ||
    /^SEO Tags:/i.test(plainText)
  ) {
    closeList();
    continue;
  }

  // Lists
  if (para.bullet?.listId) {
    const listId = para.bullet.listId;
    const tag = getListTag(listId);

    if (currentListId !== listId || currentListTag !== tag) {
      closeList();
      currentListId = listId;
      currentListTag = tag;
      html += `<${tag}>`;
    }

    html += `<li>${richText}</li>`;
    continue;
  } else {
    closeList();
  }

  // Headings and paragraphs
  if (style === 'HEADING_1') {
    if (!h1Captured) {
      h1Title = plainText;
      h1Captured = true;
    }
    // do not add H1 to html content
    continue;
  } else if (style === 'HEADING_2') {
    html += `<h2>${richText}</h2>`;
  } else if (style === 'HEADING_3') {
    html += `<h3>${richText}</h3>`;
  } else {
    html += `<p>${richText}</p>`;
  }
}

closeList();

return [
  {
    json: {
      h1Title,
      html,
      content: html,
      seoTitle,
      seoDescription,
      seoFocusKeyword,
      seoTags,
      tagNames
    }
  }
];

