  throw new Error('Gemini caption output is not valid JSON: ' + cleaned);
}

return [
  {
    json: {
      "Social Caption": parsed.main_caption || '',
      "Twitter Caption": parsed.twitter_caption || ''
    }
  }
];

const rawHtml = $('Gemini: Generate Blog HTML1').first().json.content.parts[0].text || '';
const docId = $('Google Docs: Create Draft Doc1').first().json.id;

// Keep full HTML, including SEO comments
let html = rawHtml.trim();

function stripTags(str = '') {
  return str.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

function decodeEntities(str = '') {
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

// Extract SEO fields from HTML comments
function extractSeoFields(raw = '') {
  const seo = {
    seoTitle: '',
    seoDescription: '',
    seoFocusKeyword: '',
    seoTags: ''
  };

  const titleMatch = raw.match(/<!--\s*SEO_TITLE\s*:\s*([\s\S]*?)-->/i);
  const descMatch = raw.match(/<!--\s*SEO_DESCRIPTION\s*:\s*([\s\S]*?)-->/i);
  const keywordMatch = raw.match(/<!--\s*SEO_FOCUS_KEYWORD\s*:\s*([\s\S]*?)-->/i);
  const tagsMatch = raw.match(/<!--\s*SEO_TAGS\s*:\s*([\s\S]*?)-->/i);

  seo.seoTitle = titleMatch ? titleMatch[1].trim() : '';
  seo.seoDescription = descMatch ? descMatch[1].trim() : '';
  seo.seoFocusKeyword = keywordMatch ? keywordMatch[1].trim() : '';
  seo.seoTags = tagsMatch ? tagsMatch[1].trim() : '';

  return seo;
}

const seo = extractSeoFields(rawHtml);

// Remove SEO comments only from body parsing, not from document output
html = html.replace(/<!--[\s\S]*?-->/g, '').trim();

function parseInlineParts(htmlText) {
  const parts = [];
  let remaining = htmlText;

  while (remaining.length > 0) {
    const matches = [];

    const linkMatch = remaining.match(/<a[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/i);
    if (linkMatch) {
      matches.push({
        kind: 'link',
        index: linkMatch.index,
        length: linkMatch[0].length,
        url: linkMatch[1],
        inner: linkMatch[2]
      });
    }

    const boldMatch = remaining.match(/<(strong|b)>([\s\S]*?)<\/\1>/i);
    if (boldMatch) {
      matches.push({
        kind: 'bold',
        index: boldMatch.index,
        length: boldMatch[0].length,
        inner: boldMatch[2]
      });
    }

    if (!matches.length) {
      const plain = decodeEntities(stripTags(remaining));
      if (plain) {
        parts.push({
          type: 'text',
          text: plain
        });
      }
      break;
    }

    matches.sort((a, b) => a.index - b.index);
    const next = matches[0];

    if (next.index > 0) {
      const before = decodeEntities(stripTags(remaining.slice(0, next.index)));
      if (before) {
        parts.push({
          type: 'text',
          text: before
        });
      }
    }

    if (next.kind === 'link') {
      const linkText = decodeEntities(stripTags(next.inner));
      if (linkText) {
        parts.push({
          type: 'link',
          text: linkText,
          url: next.url
        });
      }
    }

    if (next.kind === 'bold') {
      const boldText = decodeEntities(stripTags(next.inner));
      if (boldText) {
        parts.push({
          type: 'bold',
          text: boldText
        });
      }
    }

    remaining = remaining.slice(next.index + next.length);
  }

  return parts;
}

const blocks = [];
const blockRegex = /<(h1|h2|h3|p|ul|ol)([^>]*)>([\s\S]*?)<\/\1>/gi;
let blockMatch;

while ((blockMatch = blockRegex.exec(html)) !== null) {
  const tag = blockMatch[1].toLowerCase();
  const inner = blockMatch[3];

  if (tag === 'ul' || tag === 'ol') {
    const items = [...inner.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(m => m[1]);
    if (items.length) {
      blocks.push({
        type: tag,
        items
      });
    }
  } else {
    blocks.push({
      type: tag,
      html: inner
    });
  }
}

let requests = [];
let cursor = 1;

function insertText(text) {
  requests.push({
    insertText: {
      location: { index: cursor },
      text
    }
  });
  const start = cursor;
  cursor += text.length;
  return { start, end: cursor };
}

function applyParagraphStyle(start, end, namedStyleType) {
  requests.push({
    updateParagraphStyle: {
      range: {
        startIndex: start,
        endIndex: end
      },
      paragraphStyle: {
        namedStyleType
      },
      fields: 'namedStyleType'
    }
  });
}

function applyLink(start, end, url) {
  requests.push({
    updateTextStyle: {
      range: {
        startIndex: start,
        endIndex: end
      },
      textStyle: {
        link: { url }
      },
      fields: 'link'
    }
  });
}

function applyBold(start, end) {
  requests.push({
    updateTextStyle: {
      range: {
        startIndex: start,
        endIndex: end
      },
      textStyle: {
        bold: true
      },
      fields: 'bold'
    }
  });
}

function insertStyledLine(label, value, style = 'NORMAL_TEXT') {
  if (!value) return;

  const lineStart = cursor;

  const labelRange = insertText(label);
  applyBold(labelRange.start, labelRange.end);

  insertText(value);
  const lineEnd = insertText('\n');

  applyParagraphStyle(lineStart, lineEnd.end, style);
}

// Insert SEO section at top of document
if (seo.seoTitle || seo.seoDescription || seo.seoFocusKeyword || seo.seoTags) {
  const seoHeadingStart = cursor;
  const seoHeading = insertText('SEO Details\n');
  applyParagraphStyle(seoHeadingStart, seoHeading.end, 'HEADING_2');

  insertStyledLine('SEO Title: ', seo.seoTitle);
  insertStyledLine('SEO Description: ', seo.seoDescription);
  insertStyledLine('Focus Keyword: ', seo.seoFocusKeyword);
  insertStyledLine('SEO Tags: ', seo.seoTags);

  insertText('\n');
}

// Insert blog body
for (const block of blocks) {
  if (['h1', 'h2', 'h3', 'p'].includes(block.type)) {
    const startIndex = cursor;
    const parts = parseInlineParts(block.html);

    for (const part of parts) {
      const range = insertText(part.text);

      if (part.type === 'link') {
        applyLink(range.start, range.end, part.url);
      } else if (part.type === 'bold') {
        applyBold(range.start, range.end);
      }
    }

    const lineEnd = insertText('\n');

    if (block.type === 'h1') {
      applyParagraphStyle(startIndex, lineEnd.end, 'HEADING_1');
    } else if (block.type === 'h2') {
      applyParagraphStyle(startIndex, lineEnd.end, 'HEADING_2');
    } else if (block.type === 'h3') {
      applyParagraphStyle(startIndex, lineEnd.end, 'HEADING_3');
    } else {
      applyParagraphStyle(startIndex, lineEnd.end, 'NORMAL_TEXT');
    }

    insertText('\n');
  }

  if (block.type === 'ul' || block.type === 'ol') {
    const listStart = cursor;

    for (const item of block.items) {
      const parts = parseInlineParts(item);

      for (const part of parts) {
        const range = insertText(part.text);

        if (part.type === 'link') {
          applyLink(range.start, range.end, part.url);
        } else if (part.type === 'bold') {
          applyBold(range.start, range.end);
        }
      }

      insertText('\n');
    }

    const listEnd = cursor;

    requests.push({
      createParagraphBullets: {
        range: {
          startIndex: listStart,
          endIndex: listEnd
        },
        bulletPreset: block.type === 'ul'
          ? 'BULLET_DISC_CIRCLE_SQUARE'
          : 'NUMBERED_DECIMAL_NESTED'
      }
    });

    insertText('\n');
  }
}

return [
  {
    json: {
      documentId: docId,
      requests,
      rawHtml,
      seo
    }
  }
];

/*
 Build a single HTML message for Teams.
 We ignore the batch header row (Topic starting with 'Batch: ').
*/

const topics = items
  .map(i => i.json.Topic)
  .filter(t => t && !t.startsWith('Batch: '));

const htmlList = topics
  .map(t => `<li>${t}</li>`)
  .join('');

const count = topics.length;

return [
  {
    json: {
      html: `<h2><b>✅ Weekly Kleza blog topics are ready.</b></h2>\n<br><br>\n<p>${count} topics were added to the sheet.</p>\n<ul>${htmlList}</ul>\n<br>\nPlease review and tick <b>Approved</b> for the topics you want to convert into blog posts.\n<br>\nSheet Link <a href="https://docs.google.com/spreadsheets/d/1MaGXYNxpxM5QV49nAldZu9WA15Nim00tDoei9AtCRx8/edit?gid=0#gid=0">Click Here</a>`
    }
  }
];

// Split Gemini titles JSON into rows for Google Sheets

const input = $input.first().json;

// Gemini output is at: $json.output
let raw = input?.output || '';

if (!raw) {
  throw new Error('No Gemini output found at $json.output');
}

// Remove ```json ... ``` fences if present
raw = String(raw).replace(/```json|```/g, '').trim();

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Gemini output not valid JSON. Raw: ' + raw);
}

// Support both old "topics" and new "titles" formats
let items = [];
if (Array.isArray(data.titles)) {
  items = data.titles;
} else if (Array.isArray(data.topics)) {
  items = data.topics;
}

if (!items.length) {
  throw new Error(
    'No titles/topics found in JSON. Expected { "titles": [ ... ] } or { "topics": [ ... ] }. Got: ' +
      JSON.stringify(data)
  );
}

// Build Indian time (Asia/Kolkata) and format like "2nd Mar 2026, 11:20:05 AM IST"
const now = new Date();

const dateParts = new Intl.DateTimeFormat('en-IN', {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
  timeZone: 'Asia/Kolkata',
}).formatToParts(now);

const dayStr = dateParts.find((p) => p.type === 'day').value;
const monthStr = dateParts.find((p) => p.type === 'month').value;
const yearStr = dateParts.find((p) => p.type === 'year').value;

const dayNum = parseInt(dayStr, 10);

function ordinal(n) {
  const rem10 = n % 10;
  const rem100 = n % 100;
  if (rem10 === 1 && rem100 !== 11) return `${n}st`;
  if (rem10 === 2 && rem100 !== 12) return `${n}nd`;
  if (rem10 === 3 && rem100 !== 13) return `${n}rd`;
  return `${n}th`;
}

const dayWithSuffix = ordinal(dayNum);

const timeStr = new Intl.DateTimeFormat('en-IN', {
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: true,
  timeZone: 'Asia/Kolkata',
}).format(now);

const formatted = `${dayWithSuffix} ${monthStr} ${yearStr}, ${timeStr} IST`;

const output = [];

// 1) Add a header row that will appear ABOVE the topics in Google Sheets
output.push({
  json: {
    Topic: `Batch: Topics generated on ${formatted}`,
    Approved: '',
    Status: 'Batch Header',
    Notes: ''
  }
});

// 2) Add up to 5 topic/title rows
items.slice(0, 5).forEach((t) => {
  output.push({
    json: {
      Topic: String(t.title || t.topic || '').trim(),
      Approved: false,
      Status: 'Pending',
      Notes: ''
    }
  });
});

return output;

